"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Layout from "../../../components/Layout";
import FormField from "../../../components/FormFieldEdit";
import { HiArrowNarrowLeft } from "react-icons/hi";
import { Person as PersonIcon } from '@mui/icons-material';

export default function EditGroupe() {
  const [groupe, setGroupe] = useState(null);
  const [etudiants, setEtudiants] = useState([]);
  const [etudiantsDisponibles, setEtudiantsDisponibles] = useState([]);
  const [nomGroupe, setNomGroupe] = useState("");
  const { id } = useParams();
  const router = useRouter();

  useEffect(() => {
    if (id) {
      fetchGroupe();
      fetchStudentsInGroup();
      fetchAvailableStudents();
    }
  }, [id]);

  const fetchGroupe = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/groupes/${id}`);
      setGroupe(response.data);
      setNomGroupe(response.data.nomGroupe);
    } catch (err) {
      console.error("Erreur récupération groupe:", err);
      alert("Erreur lors du chargement du groupe");
    }
  };

  const fetchStudentsInGroup = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/groupes/${id}/etudiants`);
      setEtudiants(response.data);
    } catch (err) {
      console.error("Erreur récupération étudiants du groupe:", err);
    }
  };

  const fetchAvailableStudents = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/etudiants/disponibles");
      setEtudiantsDisponibles(response.data);
    } catch (err) {
      console.error("Erreur récupération étudiants disponibles:", err);
    }
  };

  const ajouterEtudiant = async (idEtudiant) => {
    try {
      await axios.put(`http://localhost:5000/api/etudiants/${idEtudiant}/groupe`, {
        idGroupe: id
      });
      
      // Refresh both student lists
      fetchStudentsInGroup();
      fetchAvailableStudents();
    } catch (err) {
      console.error("Erreur lors de l'ajout de l'étudiant:", err);
      alert("Erreur lors de l'ajout de l'étudiant");
    }
  };

  const retirerEtudiant = async (idEtudiant) => {
    try {
      await axios.put(`http://localhost:5000/api/etudiants/${idEtudiant}/groupe`, {
        idGroupe: null
      });
      
      // Refresh both student lists
      fetchStudentsInGroup();
      fetchAvailableStudents();
    } catch (err) {
      console.error("Erreur lors du retrait de l'étudiant:", err);
      alert("Erreur lors du retrait de l'étudiant");
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      await axios.put(`http://localhost:5000/api/groupes/${id}`, {
        nomGroupe: nomGroupe
      });
      router.push('/geneman');
    } catch (err) {
      console.error("Erreur modification:", err);
      alert("Erreur lors de la modification du groupe");
    }
  };

  const supprimerGroupe = async () => {
    if (!window.confirm("Voulez-vous vraiment supprimer ce groupe ?")) return;
    
    try {
      await axios.delete(`http://localhost:5000/api/groupes/${id}`);
      router.push('/geneman');
    } catch (err) {
      console.error("Erreur lors de la suppression :", err);
      alert(`Erreur: ${err.response?.data?.message || err.message}`);
    }
  };

  if (!groupe) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-amber-700"></div>
      </div>
    );
  }

  return (
    <Layout>
      <div className="flex flex-1 justify-center items-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-lg w-full max-w-4xl">
          <button
            onClick={() => router.push("/users/readgenerer")}
            className="back-button"
          >
            <HiArrowNarrowLeft className="mr-2 text-2xl" />
          </button>
   
          <h1 className="form-title text-2xl font-bold text-gray-800 text-center mb-6">
            Modifier le groupe: {groupe.nomGroupe}
          </h1>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Colonne 1: Informations du groupe */}
              <div className="space-y-4">
                <FormField
                  label="Nom du groupe"
                  name="nomGroupe"
                  value={nomGroupe}
                  onChange={(e) => setNomGroupe(e.target.value)}
                />

                <div className="pt-4">
                  <button
                    type="submit"
                    className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition-colors"
                  >
                    Enregistrer les modifications
                  </button>
                </div>

                <button
                  type="button"
                  onClick={supprimerGroupe}
                  className="w-full bg-red-600 text-white py-2 px-4 rounded-md hover:bg-red-700 transition-colors flex items-center justify-center"
                >
                  Supprimer le groupe
                </button>
              </div>

              {/* Colonne 2: Gestion des étudiants */}
              <div className="space-y-4">
                <h3 className="font-medium text-lg">Membres du groupe ({etudiants.length})</h3>
                
                <div className="border rounded-lg p-2 max-h-64 overflow-y-auto">
                  {etudiants.length > 0 ? (
                    <ul className="divide-y divide-gray-200">
                      {etudiants.map(etudiant => (
                        <li key={etudiant.idEtudiant} className="py-2 px-1 flex justify-between items-center">
                          <div className="flex items-center">
                            <PersonIcon className="text-gray-400 mr-2" />
                            <span>{etudiant.nom} {etudiant.prenom}</span>
                          </div>
                          <button
                            type="button"
                            onClick={() => retirerEtudiant(etudiant.idEtudiant)}
                            className="text-red-500 hover:text-red-700 text-sm font-medium"
                          >
                            Retirer
                          </button>
                        </li>
                      ))}
                    </ul>
                  ) : (
                    <p className="text-gray-500 text-center py-4">Aucun étudiant dans ce groupe</p>
                  )}
                </div>

                <div className="pt-2">
                  <h3 className="font-medium text-lg">Ajouter des étudiants</h3>
                  <div className="border rounded-lg p-2 max-h-64 overflow-y-auto">
                    {etudiantsDisponibles.length > 0 ? (
                      <ul className="divide-y divide-gray-200">
                        {etudiantsDisponibles.map(etudiant => (
                          <li key={etudiant.idEtudiant} className="py-2 px-1 flex justify-between items-center">
                            <div className="flex items-center">
                              <PersonIcon className="text-gray-400 mr-2" />
                              <span>{etudiant.nom} {etudiant.prenom}</span>
                            </div>
                            <button
                              type="button"
                              onClick={() => ajouterEtudiant(etudiant.idEtudiant)}
                              className="text-blue-500 hover:text-blue-700 text-sm font-medium"
                            >
                              Ajouter
                            </button>
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <p className="text-gray-500 text-center py-4">Aucun étudiant disponible</p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </form>
        </div>
      </div>
    </Layout>
  );
}